int minDistance(char *word1, char *word2) {
  int m = strlen(word1), n = strlen(word2);
  int *dp = (int *)malloc(sizeof(int) * (n + 1));
  for (int j = 0; j <= n; j++) dp[j] = j;
  for (int i = 1; i <= m; i++) {
    int prev = dp[0];
    dp[0] = i;
    for (int j = 1; j <= n; j++) {
      int tmp = dp[j];
      if (word1[i - 1] == word2[j - 1]) {
        dp[j] = prev;
      } else {
        int best = prev < dp[j] ? prev : dp[j];
        if (dp[j - 1] < best) best = dp[j - 1];
        dp[j] = best + 1;
      }
      prev = tmp;
    }
  }
  int res = dp[n];
  free(dp);
  return res;
}

class Solution {
public:
  int minDistance(string word1, string word2) {
    int m = word1.size(), n = word2.size();
    vector<int> dp(n + 1);
    for (int j = 0; j <= n; j++) dp[j] = j;
    for (int i = 1; i <= m; i++) {
      int prev = dp[0];
      dp[0] = i;
      for (int j = 1; j <= n; j++) {
        int tmp = dp[j];
        if (word1[i - 1] == word2[j - 1]) {
          dp[j] = prev;
        } else {
          dp[j] = 1 + min(prev, min(dp[j], dp[j - 1]));
        }
        prev = tmp;
      }
    }
    return dp[n];
  }
};

